// Registered as Singleton in Program.cs
public class ReportGenerator
{
    private readonly AppDbContext _context;

    public ReportGenerator(AppDbContext context)
    {
        _context = context; // Captures the first scoped instance
    }

    public async Task<Report> GenerateAsync(int userId)
    {
        // Reuses the same DbContext across all requests
        return await _context.Reports.Where(r => r.UserId == userId).ToListAsync();
    }
}

public class ReportGenerator
{
    private readonly IServiceScopeFactory _scopeFactory;

    public ReportGenerator(IServiceScopeFactory scopeFactory)
    {
        _scopeFactory = scopeFactory;
    }

    public async Task<Report> GenerateAsync(int userId)
    {
        using var scope = _scopeFactory.CreateScope();
        var context = scope.ServiceProvider.GetRequiredService<AppDbContext>();

        return await context.Reports
            .Where(r => r.UserId == userId)
            .ToListAsync();
    }
}
